/* MODULE tp07 · Bước 4 Tạo thông điệp · Viết quảng cáo: dữ kiện thay tính từ
   9 bài × 7 câu. Kỹ năng viết cụ thể: tiêu đề, lợi ích, một người đọc, CTA, 3 dòng đầu, banner, cắt chữ, mô tả trên sàn, kiểm tra trước khi chạy.
   Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tp07', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tp07-01', skill:'creative', read:'6 phút', t:'Tiêu đề này có khiến ai đọc dòng thứ hai không?',
  situation:'Một tiệm giặt sấy ở Thủ Đức chạy hai bài quảng cáo Facebook cùng ảnh, cùng ngân sách. Bài A mở bằng "Dịch vụ giặt sấy uy tín, chất lượng". Bài B mở bằng "Gửi 5 kg đồ lúc 8 giờ sáng, 5 giờ chiều nhận lại đã gấp". Mỗi bài có 20.000 lượt hiển thị. Bài A được 160 lượt bấm, bài B được 520.',
  concept:{ name:'Tiêu đề là cửa chặn',
    body:'Phần lớn người lướt chỉ đọc dòng đầu rồi quyết định dừng hay đi tiếp. Vì vậy tiêu đề không có nhiệm vụ kể hết; nhiệm vụ của nó là <b>khiến đúng người đọc dòng thứ hai</b>. Tiêu đề mạnh thường chứa một dữ kiện người đọc tự kiểm được (giờ, số, giá, kết quả) và nói về việc của họ, không phải về mình. Tiêu đề yếu là tiêu đề có thể dán cho bất kỳ tiệm nào.' },
  example:'Bài A: 160 ÷ 20.000 = 0,8% bấm. Bài B: 520 ÷ 20.000 = 2,6%. Khác biệt duy nhất là dòng đầu. "Uy tín, chất lượng" là lời tự khen, ai cũng nói được. "8 giờ gửi, 5 giờ nhận" là một lời hứa đo được và chạm đúng nỗi lo của người đi làm: tối về có quần áo sạch không. Tiệm giữ ảnh, chỉ viết lại tiêu đề cho mọi bài sau theo công thức: việc của khách + con số kiểm được.',
  takeaway:'Tiêu đề không kể hết; nó chỉ cần một dữ kiện đủ cụ thể để đúng người dừng lại.',
  apply:'Lấy tiêu đề quảng cáo gần nhất của bạn. Viết lại trong 60 giây sao cho có một con số người đọc tự kiểm được.',
  mistakes:['Dồn tên thương hiệu và mọi ưu điểm vào dòng đầu.','Viết tiêu đề chung chung đến mức đối thủ dùng lại được nguyên văn.'],
  q:[
  { type:'mcq', stem:'Hai quảng cáo cùng ảnh, cùng ngân sách, chỉ khác dòng đầu. Bạn đoán mức chênh lượt bấm có thể lớn đến đâu?',
    options:[{k:'a',t:'Gần như bằng nhau, vì ảnh mới là thứ quyết định người ta bấm'},{k:'b',t:'Có thể gấp vài lần, vì dòng đầu quyết định có đọc tiếp'},
             {k:'c',t:'Chênh khoảng vài phần trăm, không đủ để đáng thử nghiệm'},{k:'d',t:'Không đo được, vì Facebook tự chọn người xem khác nhau'}],
    answer:'b', why:{a:'Ảnh kéo mắt dừng, nhưng chữ đầu tiên quyết định người ta có thấy việc của mình trong đó không.',
      b:'Đúng. Trong tình huống, cùng ảnh nhưng bài B có lượt bấm hơn gấp ba bài A.',
      c:'Chênh lệch từ dòng đầu thường lớn hơn nhiều so với vài phần trăm, vì nó là cửa đầu tiên.',
      d:'Thử A/B cùng ngân sách, cùng tệp chính là cách đo được khác biệt do tiêu đề.'} },
  { type:'mcq', stem:'Bạn viết quảng cáo cho một tiệm sửa điện thoại. Bạn chọn dòng đầu nào?',
    options:[{k:'a',t:'Sửa điện thoại uy tín số 1 khu vực, thợ tay nghề cao lâu năm'},{k:'b',t:'Chào mừng bạn đến với tiệm sửa điện thoại của chúng tôi!'},
             {k:'c',t:'Thay pin iPhone 30 phút, ngồi chờ lấy luôn'},{k:'d',t:'Bạn có biết điện thoại cũng cần được chăm sóc như sức khoẻ?'}],
    answer:'c', why:{a:'"Uy tín số 1" là lời tự khen không kiểm được; người đọc lướt qua như mọi quảng cáo khác.',
      b:'Lời chào tốn cả dòng đầu mà không cho người đọc lý do nào để dừng.',
      c:'Đúng. Việc cụ thể và thời gian kiểm được; người đang cần thay pin dừng lại ngay.',
      d:'Câu hỏi mở vòng vo, người đọc phải đoán tiệm bán gì; phần lớn sẽ lướt qua.'} },
  { type:'calc', stem:'Bài A có 160 lượt bấm trên 20.000 lượt hiển thị. Tỉ lệ bấm (CTR) của bài A là bao nhiêu phần trăm?',
    unit:'%', ans:0.8, tol:0.01, wrong:[[125,'SAI_MAU_SO'],[8,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['CTR = lượt bấm ÷ lượt hiển thị.','160 ÷ 20.000 = 0,008 = <b>0,8%</b>.'] },
  { type:'mcq', stem:'Vì sao "Dịch vụ giặt sấy uy tín, chất lượng" là tiêu đề yếu?',
    options:[{k:'a',t:'Câu quá ngắn nên thuật toán không hiểu được nội dung bài'},{k:'b',t:'Thiếu biểu tượng cảm xúc nên không thu hút ánh mắt người lướt'},
             {k:'c',t:'Chưa nêu tên tiệm nên khách không biết ai đang quảng cáo'},{k:'d',t:'Tiệm nào cũng nói được, không có dữ kiện để kiểm'}],
    answer:'d', why:{a:'Độ dài không phải vấn đề; một câu ngắn có con số vẫn rất mạnh.',
      b:'Thêm biểu tượng không cứu được một lời hứa rỗng.',
      c:'Tên tiệm có trong trang; điều người đọc cần trước là lý do để quan tâm.',
      d:'Đúng. Lời tự khen dán được cho mọi tiệm, nên không tạo ra lý do chọn tiệm này.'} },
  { type:'mcq', stem:'Một quán cơm văn phòng ở Quận 1 muốn tiêu đề cho quảng cáo giao trưa. Câu nào làm đúng việc của tiêu đề?',
    options:[{k:'a',t:'Đặt trước 10 giờ, 11 rưỡi cơm tới bàn làm việc'},{k:'b',t:'Cơm ngon như mẹ nấu, đậm đà hương vị quê nhà thân thương'},
             {k:'c',t:'Quán cơm A — thương hiệu cơm văn phòng hàng đầu Sài Gòn'},{k:'d',t:'Ăn trưa gì hôm nay? Câu hỏi muôn thuở của dân văn phòng'}],
    answer:'a', why:{a:'Đúng. Có mốc giờ kiểm được và giải đúng nỗi lo của dân văn phòng: kịp giờ nghỉ trưa.',
      b:'"Như mẹ nấu" là câu sáo mà quán nào cũng dùng; không có gì để kiểm.',
      c:'"Hàng đầu" là lời tự nhận; người đọc không có lý do để tin.',
      d:'Gọi đúng nỗi băn khoăn nhưng không đưa ra câu trả lời, người đọc chưa biết vì sao nên chọn quán.'} },
  { type:'mcq', stem:'Tiêu đề mới có CTR cao gấp ba, nhưng số đơn không tăng. Điều gì nên kiểm tra trước?',
    options:[{k:'a',t:'Tăng ngân sách gấp ba để bù cho tỉ lệ chốt đơn còn thấp'},{k:'b',t:'Quay lại tiêu đề cũ vì tiêu đề mới rõ ràng không bán được hàng'},
             {k:'c',t:'Trang đích có giữ đúng lời hứa của tiêu đề không'},{k:'d',t:'Đổi ảnh vì CTR cao thường do ảnh chứ không do tiêu đề'}],
    answer:'c', why:{a:'Đổ thêm tiền vào một chỗ rò chỉ làm rò to hơn.',
      b:'Tiêu đề đã làm xong việc của nó là kéo người đọc tiếp; vấn đề nằm ở bước sau.',
      c:'Đúng. Nếu tiêu đề hứa "5 giờ nhận lại" mà trang đích không nhắc gì, người bấm vào sẽ bỏ đi.',
      d:'Thử nghiệm cùng ảnh đã cho thấy tiêu đề tạo ra khác biệt.'} },
  { type:'mcq', stem:'Một bạn đề xuất tiêu đề "Sale sốc cuối tuần — đừng bỏ lỡ!". Góp ý nào hữu ích nhất?',
    options:[{k:'a',t:'Thay bằng món cụ thể, mức giảm và hạn chót'},{k:'b',t:'Viết hoa toàn bộ cho khẩn cấp'},
             {k:'c',t:'Giữ nguyên, chữ "sốc" luôn kéo chú ý'},{k:'d',t:'Bỏ chữ "sale" vì khách đã chán'}],
    answer:'a', why:{a:'Đúng. "Áo thun 99k đến hết Chủ nhật" cho người đọc thứ để kiểm và để quyết.',
      b:'Viết hoa làm câu ồn hơn chứ không cụ thể hơn.',
      c:'Những chữ này xuất hiện khắp nơi nên người đọc đã quen lướt qua.',
      d:'Giảm giá vẫn là lý do mua hợp lệ; vấn đề là cách nói mơ hồ, không phải chữ "sale".'} },
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tp07-02', skill:'creative', read:'7 phút', t:'Khách mua pin 10.000 mAh hay mua "điện thoại sống qua một ngày đi công tác"?',
  situation:'Một shop phụ kiện bán sạc dự phòng 10.000 mAh, giá 290.000 đồng. Mô tả hiện tại liệt kê: "10.000 mAh, sạc nhanh 20W, cổng USB-C, nặng 210 g". Người bán thấy nhiều khách hỏi đi hỏi lại "vậy sạc được mấy lần?" rồi không mua.',
  concept:{ name:'Tính năng → lợi ích → bằng chứng',
    body:'<b>Tính năng</b> là thứ sản phẩm có. <b>Lợi ích</b> là điều khách có được nhờ tính năng đó, nói bằng ngôn ngữ đời sống của họ. Khách không tự dịch "10.000 mAh" ra "sạc đầy điện thoại mấy lần"; nếu bạn không dịch giùm, họ phải hỏi, hoặc bỏ đi. Cách viết: lấy từng tính năng, hỏi "thì sao?" cho đến khi ra một cảnh cụ thể, rồi giữ lại con số làm bằng chứng. Lợi ích không thay tính năng; lợi ích đứng trước, tính năng đứng sau làm chứng.' },
  example:'"10.000 mAh" → thì sao? → sạc đầy một điện thoại pin khoảng 4.000 mAh được hơn hai lần (tính cả hao hụt) → thì sao? → đi công tác hai ngày không cần tìm ổ cắm. "Sạc nhanh 20W" → 30 phút lên khoảng một nửa pin trong lúc chờ lên máy bay. "210 g" → nhẹ hơn một lon nước ngọt đầy, bỏ túi áo khoác được. Dòng mới: "Hai ngày công tác không cần tìm ổ cắm. 10.000 mAh, sạc 30 phút được nửa pin, nặng 210 g."',
  takeaway:'Hỏi "thì sao?" với từng tính năng cho tới khi ra cảnh khách thấy mình trong đó; giữ con số làm bằng chứng.',
  apply:'Chọn một sản phẩm bạn đang bán. Viết 3 tính năng, mỗi cái hỏi "thì sao?" hai lần và nói to kết quả.',
  mistakes:['Bỏ hẳn thông số, chỉ còn lời hứa cảm xúc không có gì để kiểm.','Dịch tính năng thành lợi ích chung chung như "tiện lợi", "an tâm".'],
  q:[
  { type:'mcq', stem:'Khách cứ hỏi "sạc được mấy lần?" rồi bỏ đi. Bạn đoán lý do chính là gì?',
    options:[{k:'a',t:'Giá 290.000 đồng quá cao so với mặt bằng chung của sạc dự phòng'},{k:'b',t:'Khách không tin thông số nên cần thêm giấy chứng nhận'},
             {k:'c',t:'Mô tả nêu tính năng nhưng chưa dịch ra điều khách có được'},{k:'d',t:'Khách chỉ hỏi cho vui, vốn không có ý định mua ngay'}],
    answer:'c', why:{a:'Nếu vướng giá, khách sẽ hỏi giảm giá; ở đây họ hỏi công dụng.',
      b:'Họ không nghi ngờ con số; họ không biết con số đó nghĩa là gì với mình.',
      c:'Đúng. Câu hỏi lặp lại chính là lợi ích mà mô tả còn thiếu.',
      d:'Khách chịu hỏi là đang cân nhắc; bỏ đi vì không có câu trả lời ngay.'} },
  { type:'mcq', stem:'Bạn viết lại dòng đầu mô tả sạc dự phòng. Bạn chọn câu nào?',
    options:[{k:'a',t:'Hai ngày công tác không cần tìm ổ cắm — 10.000 mAh, nặng 210 g'},{k:'b',t:'Sạc dự phòng 10.000 mAh, 20W, USB-C, 210 g, chính hãng'},
             {k:'c',t:'Người bạn đồng hành không thể thiếu cho cuộc sống năng động hiện đại'},{k:'d',t:'Công nghệ pin tiên tiến, an toàn tuyệt đối, bền bỉ theo thời gian'}],
    answer:'a', why:{a:'Đúng. Lợi ích đứng trước bằng một cảnh cụ thể, tính năng đứng sau làm bằng chứng.',
      b:'Chỉ là danh sách tính năng; khách vẫn phải tự dịch.',
      c:'Lợi ích cảm xúc chung chung, không có gì để kiểm và dán được cho mọi sản phẩm.',
      d:'Toàn tính từ, không có con số, không trả lời được câu "sạc mấy lần".'} },
  { type:'mcq', stem:'Tính năng "vải cotton 250 gsm" của một áo thun. Câu nào là lợi ích viết đúng cách?',
    options:[{k:'a',t:'Chất liệu cao cấp, mang lại cảm giác thoải mái tuyệt vời'},{k:'b',t:'Cotton 250 gsm — định lượng vải đạt chuẩn xuất khẩu'},
             {k:'c',t:'Áo đẹp, mặc là mê, ai thử cũng không muốn cởi ra nữa'},{k:'d',t:'Vải dày, mặc áo trắng không lộ áo trong; giặt 30 lần chưa bai cổ'}],
    answer:'d', why:{a:'"Cao cấp", "tuyệt vời" là tính từ không kiểm được.',
      b:'Vẫn là tính năng, thêm một lời tự nhận "chuẩn xuất khẩu".',
      c:'Lời khen chung chung, không gắn với tính năng nào.',
      d:'Đúng. Dịch định lượng vải ra hai cảnh khách tự kiểm được.'} },
  { type:'mcq', stem:'Một bạn đề nghị bỏ hết thông số, chỉ giữ lời "đi công tác không lo hết pin". Nhận xét nào đúng?',
    options:[{k:'a',t:'Nên giữ con số làm bằng chứng cho lời hứa'},{k:'b',t:'Đúng hướng, vì khách mua lợi ích chứ không mua thông số kỹ thuật'},
             {k:'c',t:'Nên bỏ luôn cả lợi ích, chỉ để ảnh sản phẩm nói thay lời'},{k:'d',t:'Chỉ cần thêm chữ "chính hãng" là đủ để khách tin tưởng'}],
    answer:'a', why:{a:'Đúng. Không có 10.000 mAh, lời hứa "không lo hết pin" thành lời tự khen.',
      b:'Khách mua lợi ích, nhưng tin lợi ích nhờ con số; bỏ số là bỏ bằng chứng.',
      c:'Ảnh không trả lời được câu "sạc mấy lần".',
      d:'"Chính hãng" nói về nguồn gốc, không chứng minh được thời lượng pin.'} },
  { type:'calc', stem:'Sạc dự phòng 10.000 mAh, hiệu suất thực tế khoảng 65% (phần còn lại hao hụt khi chuyển đổi). Điện thoại pin 3.250 mAh. Sạc đầy được khoảng mấy lần?',
    unit:'lần', ans:2, tol:0.05, wrong:[[3.08,'QUEN_TI_LE_CHUYEN_DOI'],[1.08,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI','SAI_TINH_TOAN'],
    steps:['Dung lượng dùng được = 10.000 × 65% = 6.500 mAh.','Số lần sạc = 6.500 ÷ 3.250 = <b>2 lần</b>.','Nếu quên hao hụt, bạn sẽ hứa hơn 3 lần — khách thử là thấy sai.'] },
  { type:'mcq', stem:'Một spa quảng cáo "máy triệt lông công nghệ Diode 808nm". Khách mục tiêu là nhân viên văn phòng. Viết lại thế nào cho đúng?',
    options:[{k:'a',t:'Công nghệ Diode 808nm hiện đại bậc nhất, nhập khẩu trực tiếp'},{k:'b',t:'Trải nghiệm làm đẹp đẳng cấp, nâng tầm vẻ đẹp phái nữ hiện đại'},
             {k:'c',t:'Làm trong giờ nghỉ trưa 30 phút; máy Diode 808nm'},{k:'d',t:'Diode 808nm — giải pháp triệt lông được hàng nghìn khách tin chọn'}],
    answer:'c', why:{a:'Vẫn chỉ là tính năng kèm lời tự khen.',
      b:'Toàn tính từ; không nói khách được gì cụ thể.',
      c:'Đúng. Lợi ích gắn với đời sống người đọc, tên công nghệ đứng sau làm bằng chứng.',
      d:'"Hàng nghìn khách" là con số mơ hồ, và lợi ích cho người đọc vẫn chưa được nói.'} },
  { type:'mcq', stem:'Khi hỏi "thì sao?" với tính năng "chống nước IP68" của đồng hồ, câu trả lời nào đi đủ sâu?',
    options:[{k:'a',t:'Thì đồng hồ chống nước rất tốt, bền bỉ với mọi điều kiện thời tiết'},{k:'b',t:'Thì đạt tiêu chuẩn quốc tế cao nhất về khả năng kháng nước'},
             {k:'c',t:'Thì khách yên tâm hơn khi sử dụng sản phẩm hằng ngày'},{k:'d',t:'Thì đeo đi bơi, rửa bát, tắm không cần tháo'}],
    answer:'d', why:{a:'Chỉ nói lại tính năng bằng tính từ.',
      b:'Vẫn đứng ở phía sản phẩm, chưa sang đời sống khách.',
      c:'"Yên tâm" đúng nhưng chung chung; chưa ra cảnh cụ thể.',
      d:'Đúng. Ba cảnh cụ thể khách tự thấy mình trong đó.'} },
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tp07-03', skill:'creative', read:'6 phút', t:'Viết cho "quý khách hàng" hay viết cho chị Lan?',
  situation:'Một trung tâm tiếng Anh ở Đà Nẵng viết quảng cáo lớp giao tiếp: "Chúng tôi mang đến cho quý học viên mọi lứa tuổi môi trường học tập hiện đại". Tệp mục tiêu thật ra là nhân viên văn phòng 25–32 tuổi cần nói tiếng Anh khi họp với khách nước ngoài. Bài chạy hai tuần, 40 lượt nhắn, phần lớn là phụ huynh hỏi lớp cho con.',
  concept:{ name:'Viết cho một người',
    body:'Khi viết cho "mọi người", câu chữ tự động chung chung vì phải hợp với tất cả. Cách chữa: trước khi viết, dựng <b>một người đọc cụ thể</b> — tên, tuổi, việc, một khoảnh khắc khó khăn cụ thể — rồi viết như nhắn tin cho đúng người đó. Xưng "bạn" thay "quý khách", nói về tình huống của họ thay vì về "chúng tôi". Viết cho một người không làm mất người khác; nó làm đúng người nhận ra mình, và làm sai người tự lọc ra.' },
  example:'Người đọc: chị Lan, 28 tuổi, kế toán ở công ty logistics, tuần sau có cuộc họp trực tuyến với khách Hàn Quốc nói tiếng Anh, sợ nhất là bị hỏi mà không trả lời được. Quảng cáo mới: "Họp với khách nước ngoài mà cứ im lặng khi bị hỏi? Lớp 8 buổi tối thứ 3–5, luyện đúng 20 câu hay gặp trong cuộc họp." Phụ huynh đọc thấy không phải lớp cho con nên không nhắn; người như chị Lan thấy mình trong câu đầu.',
  takeaway:'Viết như nhắn tin cho một người thật; đúng người sẽ nhận ra mình, sai người tự đi qua.',
  apply:'Viết 3 dòng mô tả người đọc của quảng cáo tiếp theo: tên, việc, một khoảnh khắc khó. Rồi viết câu đầu như nhắn cho họ.',
  mistakes:['Sợ mất khách nên viết cho "mọi lứa tuổi".','Nói về "chúng tôi" nhiều hơn nói về người đọc.'],
  q:[
  { type:'mcq', stem:'Quảng cáo cho nhân viên văn phòng nhưng phụ huynh nhắn nhiều nhất. Bạn đoán nguyên nhân chính?',
    options:[{k:'a',t:'Phụ huynh vốn là tệp thích nhắn tin hỏi han hơn người đi làm'},{k:'b',t:'Ảnh quảng cáo có trẻ em nên thuật toán đẩy nhầm cho phụ huynh'},
             {k:'c',t:'Ngân sách hai tuần quá ít để tìm đúng người trong tệp'},{k:'d',t:'Câu chữ viết cho "mọi lứa tuổi" nên không nói với ai'}],
    answer:'d', why:{a:'Có thể phụ huynh nhắn nhiều, nhưng lý do gốc là bài không gọi đúng người đi làm.',
      b:'Tình huống không nói có ảnh trẻ em; câu chữ đã đủ mời mọi đối tượng.',
      c:'40 lượt nhắn cho thấy bài có tiếp cận; vấn đề là tiếp cận sai người.',
      d:'Đúng. "Mọi lứa tuổi" mời ai cũng được, và người có nhu cầu học cho con phản hồi trước.'} },
  { type:'mcq', stem:'Bạn viết lại câu đầu cho lớp giao tiếp. Bạn chọn câu nào?',
    options:[{k:'a',t:'Trung tâm với đội ngũ giáo viên bản ngữ giàu kinh nghiệm nhiều năm'},{k:'b',t:'Họp với khách nước ngoài mà cứ im lặng khi bị hỏi?'},
             {k:'c',t:'Kính chào quý học viên, chương trình ưu đãi tháng 10 đã bắt đầu'},{k:'d',t:'Tiếng Anh là chìa khoá mở cánh cửa thành công cho mọi người'}],
    answer:'b', why:{a:'Nói về "chúng tôi", không nói với ai.',
      b:'Đúng. Gọi đúng một khoảnh khắc khó của người đi làm; họ nhận ra mình ngay.',
      c:'"Quý học viên" là lối viết cho đám đông, và câu không nói lớp này cho ai.',
      d:'Câu sáo, đúng với mọi người nên không chạm ai.'} },
  { type:'mcq', stem:'Viết cho một người cụ thể có làm mất những khách khác không?',
    options:[{k:'a',t:'Có, nên luôn viết cho đám đông để tối đa hoá số người quan tâm'},{k:'b',t:'Có, nên chạy thêm nhiều bài song song, mỗi bài cho một nhóm tuổi'},
             {k:'c',t:'Không đáng kể; người đúng nhận ra mình, người sai tự lọc'},{k:'d',t:'Không, vì thuật toán tự tìm người phù hợp bất kể câu chữ viết gì'}],
    answer:'c', why:{a:'Viết cho đám đông kéo nhiều lượt hỏi sai người như tình huống 40 tin nhắn.',
      b:'Chia nhỏ theo tuổi vẫn là chia theo nhân khẩu học, chưa phải theo khoảnh khắc cụ thể.',
      c:'Đúng. Người không có nhu cầu đó vốn không phải khách của lớp này.',
      d:'Thuật toán học từ ai tương tác; câu chữ chung chung khiến nó học sai người.'} },
  { type:'mcq', stem:'Cách xưng hô nào hợp với viết cho một người, cho quảng cáo mỹ phẩm nhắm sinh viên?',
    options:[{k:'a',t:'"Quý khách hàng thân mến" để thể hiện sự tôn trọng'},{k:'b',t:'"Chúng tôi tự hào mang đến" để khẳng định thương hiệu'},
             {k:'c',t:'"Các bạn, các anh chị, các cô chú" để không bỏ sót ai'},{k:'d',t:'"Bạn", nói về da của bạn, như bạn thân nhắn tin'}],
    answer:'d', why:{a:'Trang trọng quá khiến sinh viên thấy như đọc thông báo.',
      b:'Đặt thương hiệu vào giữa thay vì người đọc.',
      c:'Gọi tất cả cùng lúc là quay lại viết cho đám đông.',
      d:'Đúng. Xưng "bạn" và nói về vấn đề của họ là viết cho một người.'} },
  { type:'mcq', stem:'Một tiệm bánh kem viết cho "chị em công sở bận rộn". Bước tiếp theo để cụ thể hơn là gì?',
    options:[{k:'a',t:'Chọn một khoảnh khắc: 4 giờ chiều nhớ ra sinh nhật đồng nghiệp'},{k:'b',t:'Mở rộng thành "mọi người yêu bánh ngọt" để có thêm khách'},
             {k:'c',t:'Thêm độ tuổi 22–35 và thu nhập vào phần mô tả người đọc'},{k:'d',t:'Đổi thành "doanh nghiệp" để nhận thêm đơn số lượng lớn'}],
    answer:'a', why:{a:'Đúng. Khoảnh khắc cụ thể cho câu chữ một cảnh; bánh giao trong 2 giờ trở thành lời hứa đúng lúc.',
      b:'Đi ngược hướng: càng rộng càng chung chung.',
      c:'Tuổi và thu nhập giúp chọn tệp nhưng không cho bạn biết viết câu gì.',
      d:'Đổi sang khách khác hẳn, không làm tệp hiện tại rõ hơn.'} },
  { type:'mcq', stem:'Đọc lại bản nháp, bạn đếm được 9 lần chữ "chúng tôi" và 1 lần chữ "bạn". Nên sửa gì?',
    options:[{k:'a',t:'Giữ nguyên, vì khách cần biết rõ doanh nghiệp là ai trước tiên'},{k:'b',t:'Chuyển câu về phía người đọc: "bạn được gì", "bạn đỡ việc gì"'},
             {k:'c',t:'Đổi hết "chúng tôi" thành tên thương hiệu để tăng nhận diện'},{k:'d',t:'Thêm lời cảm ơn khách hàng ở cuối để cân bằng giọng văn'}],
    answer:'b', why:{a:'Khách quan tâm việc của họ trước; giới thiệu doanh nghiệp để sau.',
      b:'Đúng. Tỉ lệ 9:1 cho thấy bài đang nói về mình; xoay câu về người đọc.',
      c:'Thay chữ nhưng vẫn nói về mình.',
      d:'Lời cảm ơn cuối bài không sửa được 9 câu tự nói về mình.'} },
  { type:'calc', stem:'Trong 40 lượt nhắn của bài quảng cáo cũ, 28 lượt là phụ huynh hỏi lớp cho con. Bao nhiêu phần trăm lượt nhắn đến từ đúng tệp người đi làm?',
    unit:'%', ans:30, tol:0.1, wrong:[[70,'SAI_TINH_TOAN'],[42.9,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Lượt nhắn đúng tệp = 40 − 28 = 12.','Tỉ lệ = 12 ÷ 40 = <b>30%</b>.','70% là phần sai tệp; 42,9% là chia 12 cho 28 — sai mẫu số.'] },
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tp07-04', skill:'creative', read:'6 phút', t:'"Liên hệ ngay" hay "Nhắn chữ SIZE để được tư vấn trong 5 phút"?',
  situation:'Một shop giày nữ trên Facebook kết thúc mọi bài bằng "Liên hệ ngay để được tư vấn!". Mỗi bài có khoảng 2.000 lượt đọc hết, 30 tin nhắn. Nhân viên phải hỏi lại từng người "chị đi size mấy, muốn mẫu nào". Shop thử kết bài bằng "Nhắn chữ SIZE + số chân, shop gửi ảnh mẫu còn hàng trong 5 phút".',
  concept:{ name:'Câu kêu gọi hành động (CTA) rõ',
    body:'CTA tốt trả lời ba câu người đọc đang tự hỏi: <b>làm gì</b> (một hành động duy nhất, dễ nhất có thể), <b>được gì ngay</b> (điều xảy ra sau khi làm), và <b>vì sao bây giờ</b> (nếu có hạn thật). "Liên hệ ngay" bắt người đọc tự nghĩ nên viết gì — mỗi lần phải nghĩ là một lần có người bỏ đi. CTA càng ít bước suy nghĩ thì càng nhiều người làm theo.' },
  example:'Sau khi đổi, cùng khoảng 2.000 lượt đọc hết, shop nhận 90 tin nhắn thay vì 30. Tỉ lệ nhắn từ 1,5% lên 4,5%. Quan trọng hơn: tin nhắn đã có số chân, nhân viên gửi ảnh mẫu còn size ngay, không phải hỏi lại. Shop không thêm "gấp", "sốc", chỉ làm hành động đơn giản hơn và nói rõ điều khách nhận được.',
  takeaway:'CTA tốt nói rõ một việc dễ làm và điều khách nhận ngay sau đó.',
  apply:'Viết lại CTA của bài đăng gần nhất: một động từ cụ thể, một điều khách nhận được, trong 15 chữ.',
  mistakes:['Đưa cùng lúc ba lựa chọn: gọi, nhắn, ghé cửa hàng.','Tạo khẩn cấp giả ("chỉ hôm nay") khi hôm sau vẫn chạy.'],
  q:[
  { type:'mcq', stem:'Đổi "Liên hệ ngay" thành "Nhắn chữ SIZE + số chân". Bạn đoán số tin nhắn thay đổi thế nào?',
    options:[{k:'a',t:'Tăng, vì khách không phải nghĩ nên nhắn gì'},{k:'b',t:'Giảm, vì yêu cầu nhắn đúng cú pháp làm khách thấy phiền'},
             {k:'c',t:'Giữ nguyên, vì người muốn mua thì kiểu gì cũng liên hệ'},{k:'d',t:'Tăng nhẹ, nhưng toàn khách tò mò không có ý định mua'}],
    answer:'a', why:{a:'Đúng. Trong tình huống, tin nhắn tăng từ 30 lên 90 với cùng lượt đọc.',
      b:'Nhắn một chữ và một số dễ hơn tự nghĩ câu hỏi.',
      c:'Nhiều người muốn mua vẫn bỏ đi khi phải nghĩ nên hỏi gì.',
      d:'Khách chịu gửi số chân là đã hình dung mình đi đôi giày đó.'} },
  { type:'mcq', stem:'Bạn viết CTA cho bài quảng cáo lớp yoga buổi sáng. Bạn chọn câu nào?',
    options:[{k:'a',t:'Hãy liên hệ với chúng tôi để biết thêm chi tiết về các lớp học'},{k:'b',t:'Gọi, nhắn tin, hoặc ghé trực tiếp studio — chúng tôi luôn sẵn sàng'},
             {k:'c',t:'Đăng ký ngay kẻo lỡ, ưu đãi sốc không thể bỏ qua!!!'},{k:'d',t:'Bấm "Đặt buổi thử" để giữ chỗ 6 giờ sáng thứ Bảy'}],
    answer:'d', why:{a:'Không nói làm gì cụ thể, không nói được gì.',
      b:'Ba lựa chọn khiến người đọc phải cân nhắc, và nhiều người không chọn gì.',
      c:'Khẩn cấp chung chung, không nói hành động cụ thể là gì.',
      d:'Đúng. Một hành động, một điều nhận được, một mốc giờ cụ thể.'} },
  { type:'calc', stem:'Sau khi đổi CTA, bài có 2.000 lượt đọc hết và 90 tin nhắn. Tỉ lệ nhắn tin trên lượt đọc hết là bao nhiêu phần trăm?',
    unit:'%', ans:4.5, tol:0.05, wrong:[[1.5,'SAI_TINH_TOAN'],[2222.2,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Tỉ lệ = tin nhắn ÷ lượt đọc hết.','90 ÷ 2.000 = 0,045 = <b>4,5%</b>.','1,5% là con số cũ với 30 tin nhắn.'] },
  { type:'mcq', stem:'CTA "Nhắn ngay, chỉ hôm nay giảm 50%" nhưng tuần sau shop vẫn chạy mức giảm đó. Hậu quả nào đáng lo nhất?',
    options:[{k:'a',t:'Đối thủ sẽ biết giá và hạ giá theo ngay lập tức'},{k:'b',t:'Khách học được rằng "chỉ hôm nay" của shop không thật'},
             {k:'c',t:'Chi phí quảng cáo tăng vì bài chạy lâu hơn dự kiến'},{k:'d',t:'Facebook phạt bài vì dùng cụm từ khẩn cấp quá nhiều'}],
    answer:'b', why:{a:'Giá công khai vốn đã ai cũng xem được; đây không phải rủi ro chính.',
      b:'Đúng. Hạn chót giả làm mất niềm tin cho mọi hạn chót sau này.',
      c:'Chi phí là chuyện ngân sách, không phải hậu quả của CTA.',
      d:'Không có căn cứ; rủi ro thật nằm ở niềm tin của khách.'} },
  { type:'mcq', stem:'Một bài quảng cáo có CTA: "Tải app, đăng ký tài khoản, xác minh số điện thoại để nhận mã 30k". Góp ý nào đúng?',
    options:[{k:'a',t:'Giữ nguyên vì mã 30k đủ hấp dẫn để khách vượt qua ba bước'},{k:'b',t:'Tăng mã lên 50k để bù cho độ phức tạp của các bước đăng ký'},
             {k:'c',t:'CTA chỉ nêu bước đầu; các bước sau để app dẫn'},{k:'d',t:'Thêm "nhanh tay" vào đầu câu để tạo động lực cho khách'}],
    answer:'c', why:{a:'Ba bước trong một câu làm người đọc thấy mệt trước khi bắt đầu.',
      b:'Tăng tiền không làm câu dễ hiểu hơn.',
      c:'Đúng. "Tải app, nhận ngay mã 30k" — một bước, một phần thưởng; app hướng dẫn tiếp.',
      d:'Thúc giục không bớt được bước nào.'} },
  { type:'mcq', stem:'Một nhà hàng lẩu có CTA "Đặt bàn ngay". Thêm gì để trả lời "được gì ngay"?',
    options:[{k:'a',t:'Thêm "hotline 24/7, gọi giờ nào cũng có người nghe máy"'},{k:'b',t:'"Đặt bàn qua Zalo, nhận xác nhận trong 10 phút, giữ bàn đến 19 giờ"'},
             {k:'c',t:'Thêm dấu chấm than cho nổi'},{k:'d',t:'Thêm "uy tín, phục vụ tận tâm, không gian sang trọng từ 2010"'}],
    answer:'b', why:{a:'Nói cách liên lạc, chưa nói điều khách nhận được.',
      b:'Đúng. Khách biết xác nhận khi nào và bàn được giữ tới giờ nào.',
      c:'Trang trí thêm không trả lời câu hỏi nào của khách.',
      d:'Tính từ tự khen, không phải điều khách nhận được.'} },
  { type:'mcq', stem:'Trong một bài, bạn đặt hai nút: "Mua ngay" và "Xem thêm sản phẩm khác". Vấn đề là gì?',
    options:[{k:'a',t:'Không có vấn đề, vì nhiều lựa chọn giúp khách thấy thoải mái hơn'},{k:'b',t:'Nút thứ hai nên viết hoa để cân với nút thứ nhất'},
             {k:'c',t:'Nên thêm nút thứ ba "Gọi tư vấn" để phục vụ khách lớn tuổi'},{k:'d',t:'Hai hành động chia chú ý; người đang phân vân chọn lối thoát'}],
    answer:'d', why:{a:'Với quảng cáo, thêm lựa chọn thường làm giảm hành động chính.',
      b:'Định dạng không giải quyết việc chia chú ý.',
      c:'Thêm nút càng làm rối hơn.',
      d:'Đúng. Mỗi quảng cáo một hành động chính; lối "xem thêm" kéo người phân vân rời đi.'} },
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tp07-05', skill:'channel', read:'7 phút', t:'Ba dòng đầu caption: khách có bấm "xem thêm" không?',
  situation:'Một thương hiệu cà phê rang xay ở Buôn Ma Thuột đăng bài Facebook bán combo 500 g. Caption mở bằng: "Xin chào cả nhà! Hôm nay mình rất vui được chia sẻ với mọi người một câu chuyện về hành trình...". Thông tin quan trọng — giá 145.000 đồng, rang mộc, giao 2 ngày — nằm ở dòng thứ tám, sau nút "Xem thêm".',
  concept:{ name:'Vùng hiển thị trước "xem thêm"',
    body:'Trên bảng tin Facebook và phần mô tả TikTok, người xem chỉ thấy <b>khoảng 2–3 dòng đầu</b> trước khi chữ bị cắt. Đây là toàn bộ quảng cáo đối với phần lớn người lướt. Ba dòng đầu phải tự đứng được: ai nên đọc, họ được gì, và một chi tiết cụ thể. Lời chào, câu chuyện dẫn, hashtag đều để sau. Với video TikTok, câu nói trong 2 giây đầu và chữ trên màn hình đóng vai trò tương tự.' },
  example:'Viết lại ba dòng đầu: "Cà phê rang mộc, không tẩm bơ, không hương liệu. 500 g pha được khoảng 50 ly phin, 145.000 đồng. Rang thứ Hai, giao tới Sài Gòn thứ Tư." Người chỉ đọc ba dòng vẫn biết sản phẩm là gì, giá mỗi ly khoảng 2.900 đồng, và độ tươi. Câu chuyện hành trình của vườn cà phê chuyển xuống dưới cho người muốn đọc thêm.',
  takeaway:'Coi ba dòng đầu là cả quảng cáo; phần dưới "xem thêm" chỉ dành cho người đã quan tâm.',
  apply:'Mở bài đăng gần nhất của bạn, che mọi thứ sau dòng thứ ba. Nói to: người chỉ đọc chừng đó có biết bạn bán gì, giá bao nhiêu không?',
  mistakes:['Mở bằng lời chào hoặc "hôm nay mình kể chuyện".','Dồn hashtag và biểu tượng lên đầu, đẩy thông tin xuống.'],
  q:[
  { type:'mcq', stem:'Caption cà phê để giá và thông tin giao hàng ở dòng thứ tám. Bạn đoán phần lớn người lướt thấy gì?',
    options:[{k:'a',t:'Thấy đủ, vì người quan tâm cà phê sẽ luôn bấm xem thêm'},{k:'b',t:'Thấy ảnh là đủ, vì ảnh đã thể hiện hết chất lượng sản phẩm'},
             {k:'c',t:'Chỉ thấy lời chào, không biết giá hay sản phẩm'},{k:'d',t:'Thấy giá, vì Facebook tự đưa con số lên phần xem trước'}],
    answer:'c', why:{a:'Họ chỉ bấm khi ba dòng đầu cho họ lý do; lời chào không phải lý do.',
      b:'Ảnh không cho biết giá, độ rang, hay thời gian giao.',
      c:'Đúng. Phần hiển thị chỉ gồm lời chào và câu dẫn chuyện.',
      d:'Nền tảng không tự chọn thông tin nào để hiện; nó cắt theo số dòng.'} },
  { type:'mcq', stem:'Bạn viết lại ba dòng đầu cho combo cà phê. Bạn chọn bản nào?',
    options:[{k:'a',t:'Rang mộc, không hương liệu. 500 g ≈ 50 ly phin, 145.000đ. Giao 2 ngày.'},{k:'b',t:'Xin chào cả nhà yêu cà phê! Cùng mình khám phá hương vị đại ngàn nhé.'},
             {k:'c',t:'#caphe #rangmoc #buonmathuot #caphesach #coffee #vietnam #ngon'},{k:'d',t:'Câu chuyện bắt đầu từ năm 1995, khi ông nội tôi trồng cây cà phê đầu tiên...'}],
    answer:'a', why:{a:'Đúng. Sản phẩm, giá, lượng dùng và thời gian giao — đủ để quyết định trong ba dòng.',
      b:'Lời chào và câu mời chung chung, chưa có thông tin gì.',
      c:'Hashtag chiếm hết vùng hiển thị mà không nói gì với người đọc.',
      d:'Câu chuyện hay nhưng để ở đầu thì người lướt không biết bạn bán gì.'} },
  { type:'calc', stem:'Gói cà phê 500 g giá 145.000 đồng, mỗi ly phin dùng 10 g. Giá mỗi ly là bao nhiêu đồng?',
    unit:'đồng', ans:2900, tol:1, wrong:[[290,'SAI_TINH_TOAN'],[14500,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Số ly = 500 ÷ 10 = 50 ly.','Giá mỗi ly = 145.000 ÷ 50 = <b>2.900 đồng</b>.'] },
  { type:'mcq', stem:'Một video TikTok bán kem chống nắng mở bằng 4 giây logo xoay kèm nhạc. Nên sửa gì trước?',
    options:[{k:'a',t:'Làm logo to hơn và đổi màu cho nổi bật trên nền video'},{k:'b',t:'Kéo dài phần logo lên 6 giây để khách nhớ thương hiệu hơn'},
             {k:'c',t:'Đổi nhạc nền sang bài đang thịnh hành để thuật toán đẩy video tới nhiều người xem hơn'},{k:'d',t:'Mở bằng câu nói và chữ nêu vấn đề: "Bôi xong không bết, không trắng mặt"'}],
    answer:'d', why:{a:'Logo to hơn vẫn là 4 giây người xem không có lý do ở lại.',
      b:'Càng dài càng mất người xem trước khi tới nội dung.',
      c:'Nhạc giúp phân phối nhưng không cho người xem lý do dừng.',
      d:'Đúng. Vài giây đầu của video đóng vai trò như ba dòng đầu caption.'} },
  { type:'mcq', stem:'Caption bài bán balo có dòng đầu "Balo chống nước, ngăn laptop 15.6 inch, 390k". Nên đặt hashtag ở đâu?',
    options:[{k:'a',t:'Ở dòng đầu tiên để thuật toán hiểu chủ đề ngay từ đầu'},{k:'b',t:'Ở cuối caption, sau thông tin chính'},
             {k:'c',t:'Xen giữa các câu để caption trông sinh động, bắt mắt hơn'},{k:'d',t:'Bỏ hẳn, vì hashtag không còn tác dụng gì trên các nền tảng'}],
    answer:'b', why:{a:'Chiếm chỗ của thông tin người đọc cần trong vùng hiển thị.',
      b:'Đúng. Hashtag vẫn có ích cho phân loại, nhưng không được chiếm ba dòng đầu.',
      c:'Xen giữa làm câu khó đọc.',
      d:'Hashtag vẫn giúp phân loại nội dung; chỉ là đặt sai chỗ thì hại.'} },
  { type:'mcq', stem:'Muốn biết ba dòng đầu có làm việc không, số liệu nào nên xem?',
    options:[{k:'a',t:'Số lượt chia sẻ bài viết trong tuần đầu'},{k:'b',t:'Số người theo dõi trang tăng thêm sau khi bài được đăng lên'},
             {k:'c',t:'Tỉ lệ bấm "xem thêm" hoặc bấm liên kết trên lượt hiển thị'},{k:'d',t:'Tổng số bình luận, kể cả những bình luận chỉ gắn thẻ bạn bè vào'}],
    answer:'c', why:{a:'Chia sẻ phụ thuộc toàn bài, không riêng phần mở đầu.',
      b:'Theo dõi trang chịu ảnh hưởng của nhiều thứ khác.',
      c:'Đúng. Đây là hành động trực tiếp xảy ra sau khi đọc ba dòng đầu.',
      d:'Bình luận gắn thẻ đo mức lan truyền, không đo ba dòng đầu có kéo người đọc tiếp.'} },
  { type:'mcq', stem:'Một bạn nói: "Mở bằng câu chuyện mới tạo cảm xúc, bán hàng ngay ở đầu thì thô". Phản hồi nào hợp lý?',
    options:[{k:'a',t:'Đúng, bài bán hàng nên luôn mở bằng câu chuyện dài'},{k:'b',t:'Sai, không bao giờ nên kể chuyện trong bài quảng cáo'},
             {k:'c',t:'Đúng, vì khách Việt thích được chào hỏi trước khi mua'},{k:'d',t:'Chuyện vẫn được, miễn câu đầu đã cho thấy người đọc được gì'}],
    answer:'d', why:{a:'Chuyện dài ở đầu làm mất người lướt trước khi họ biết bạn bán gì.',
      b:'Kể chuyện có chỗ; vấn đề chỉ là thứ tự.',
      c:'Lời chào tốn vùng hiển thị quý nhất mà không cho lý do dừng.',
      d:'Đúng. Mở bằng một câu chuyện có con số hoặc khoảnh khắc cụ thể vẫn làm được việc của ba dòng đầu.'} },
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tp07-06', skill:'creative', read:'6 phút', t:'Banner 300×250 có chỗ cho bao nhiêu chữ?',
  situation:'Một chuỗi nhà thuốc chạy banner hiển thị kích thước 300×250 trên các trang tin. Bản thiết kế đầu có 42 chữ: tên chuỗi, khẩu hiệu, bốn dòng ưu đãi, địa chỉ website, số hotline và nút "Xem ngay". Trên điện thoại, chữ nhỏ tới mức phải phóng to mới đọc được.',
  concept:{ name:'Một banner, một ý',
    body:'Banner nhỏ được nhìn trong khoảng một hai giây, bằng khoé mắt, khi người ta đang đọc thứ khác. Vì vậy nó chỉ mang được <b>một ý</b>: một lời hứa ngắn (thường dưới 8 chữ), một dấu hiệu nhận ra thương hiệu (logo, màu), và một nút. Những gì còn lại — điều kiện, địa chỉ, danh sách ưu đãi — để ở trang đích. Nếu có nhiều ưu đãi, làm nhiều banner, mỗi cái một ưu đãi, rồi xem cái nào hiệu quả.' },
  example:'Nhà thuốc cắt 42 chữ xuống còn 9: "Giao thuốc trong 1 giờ" (6 chữ), logo, nút "Đặt ngay". Ba ưu đãi còn lại tách thành ba banner khác. Sau hai tuần, banner "Giao thuốc trong 1 giờ" có CTR 0,45%, gấp ba bản 42 chữ (0,15%). Hotline và địa chỉ chuyển lên đầu trang đích, nơi người đã bấm vào có thời gian đọc.',
  takeaway:'Banner nhỏ mang đúng một ý; mọi thứ khác thuộc về trang đích.',
  apply:'Chọn ưu đãi mạnh nhất của bạn. Viết nó trong tối đa 7 chữ, có một con số.',
  mistakes:['Nhét mọi ưu đãi vào một banner "cho đủ".','Để chữ trên ảnh nền rối, không đọc được ở màn hình nhỏ.'],
  q:[
  { type:'mcq', stem:'Banner 42 chữ trên điện thoại. Bạn đoán người lướt đọc được bao nhiêu?',
    options:[{k:'a',t:'Hầu hết, vì người đọc báo thường đọc kỹ các quảng cáo xung quanh'},{k:'b',t:'Khoảng một nửa, đủ để nắm được ưu đãi chính của nhà thuốc'},
             {k:'c',t:'Gần như không chữ nào; họ chỉ liếc qua'},{k:'d',t:'Đọc đủ nếu dùng phông chữ đậm và có nhiều màu sắc tương phản'}],
    answer:'c', why:{a:'Người đọc báo tập trung vào bài báo; banner nằm ở khoé mắt.',
      b:'Trong một hai giây liếc qua, chữ nhỏ gần như không được đọc.',
      c:'Đúng. Với 42 chữ nhỏ, mắt không dừng được ở ý nào.',
      d:'Phông đậm giúp một chút, nhưng 42 chữ vẫn quá nhiều cho một cái liếc.'} },
  { type:'mcq', stem:'Nhà thuốc có bốn ưu đãi. Bạn làm gì với banner 300×250?',
    options:[{k:'a',t:'Giữ bốn ưu đãi nhưng thu nhỏ phông chữ để vừa với khung hình'},{k:'b',t:'Làm banner động xoay vòng bốn ưu đãi, mỗi cái hiện 0,5 giây'},
             {k:'c',t:'Chỉ ghi tên chuỗi và logo, bỏ hết ưu đãi cho gọn gàng'},{k:'d',t:'Tách bốn banner, mỗi cái một ưu đãi, rồi so kết quả'}],
    answer:'d', why:{a:'Nhỏ hơn thì càng không đọc được.',
      b:'Nửa giây mỗi khung là quá nhanh; người liếc qua chỉ thấy chuyển động.',
      c:'Mất lý do để bấm; người ta không bấm vào một logo.',
      d:'Đúng. Mỗi banner một ý, và bạn học được ưu đãi nào kéo người bấm nhất.'} },
  { type:'mcq', stem:'Câu nào hợp nhất cho banner nhỏ của một hãng bảo hiểm xe máy?',
    options:[{k:'a',t:'Bảo hiểm xe máy 66k/năm, mua 2 phút'},{k:'b',t:'Giải pháp bảo hiểm toàn diện, uy tín hàng đầu, phục vụ tận tâm'},
             {k:'c',t:'An tâm trên mọi nẻo đường cùng người bạn đồng hành tin cậy'},{k:'d',t:'Bảo hiểm xe máy, ô tô, sức khoẻ, du lịch, nhà ở — đủ loại'}],
    answer:'a', why:{a:'Đúng. Một ý, một con số, một lời hứa đo được, đọc trong một cái liếc.',
      b:'Toàn tính từ; không mang ý nào cụ thể.',
      c:'Câu sáo, dài và không có gì để nhớ.',
      d:'Năm ý trong một banner, không ý nào đọng lại.'} },
  { type:'calc', stem:'Banner mới có 12.000 lượt hiển thị và 54 lượt bấm. CTR là bao nhiêu phần trăm?',
    unit:'%', ans:0.45, tol:0.01, wrong:[[4.5,'SAI_TINH_TOAN'],[222.2,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['CTR = lượt bấm ÷ lượt hiển thị.','54 ÷ 12.000 = 0,0045 = <b>0,45%</b>.'] },
  { type:'mcq', stem:'Điều kiện áp dụng ưu đãi ("đơn từ 200k, nội thành") nên đặt ở đâu?',
    options:[{k:'a',t:'Chữ nhỏ ở góc dưới banner để đảm bảo minh bạch với khách'},{k:'b',t:'Ở trang đích, ngay cạnh lời hứa trên banner'},
             {k:'c',t:'Không cần nêu, khách tự hỏi khi đặt hàng là đủ rồi'},{k:'d',t:'Ở dòng chính của banner, thay cho lời hứa giao nhanh'}],
    answer:'b', why:{a:'Chữ nhỏ trên banner không ai đọc, lại lấy chỗ của ý chính.',
      b:'Đúng. Người đã bấm có thời gian đọc; điều kiện đứng ngay cạnh lời hứa để khỏi hiểu lầm.',
      c:'Giấu điều kiện làm khách thấy bị lừa khi đặt hàng.',
      d:'Điều kiện không phải lý do để bấm.'} },
  { type:'mcq', stem:'Banner có chữ trắng đặt trên ảnh cửa hàng nhiều màu. Góp ý nào hữu ích nhất?',
    options:[{k:'a',t:'Thêm viền chữ bảy màu cho nổi hơn trên nền ảnh'},{k:'b',t:'Dùng ảnh cửa hàng đẹp hơn, độ phân giải cao hơn'},
             {k:'c',t:'Đặt chữ trên mảng màu trơn để đọc được ở cỡ nhỏ'},{k:'d',t:'Bỏ chữ, để ảnh cửa hàng tự nói lên chất lượng dịch vụ'}],
    answer:'c', why:{a:'Thêm màu làm banner rối hơn.',
      b:'Ảnh đẹp hơn vẫn là nền rối dưới chữ.',
      c:'Đúng. Độ tương phản quan trọng hơn ảnh đẹp khi banner chỉ được liếc qua.',
      d:'Ảnh cửa hàng không nói được lời hứa "giao trong 1 giờ".'} },
  { type:'mcq', stem:'Sếp muốn thêm khẩu hiệu thương hiệu vào mọi banner nhỏ "cho nhất quán". Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý, khẩu hiệu quan trọng hơn ưu đãi nên phải nằm trên cùng'},{k:'b',t:'Đồng ý, thu nhỏ lời hứa lại để có chỗ cho khẩu hiệu dài'},
             {k:'c',t:'Từ chối, banner nhỏ không nên có bất kỳ dấu hiệu thương hiệu nào'},{k:'d',t:'Giữ logo và màu để nhận ra; một ý duy nhất vẫn là lời hứa'}],
    answer:'d', why:{a:'Hai ý cạnh tranh trong một cái liếc; thường cả hai đều không được đọc.',
      b:'Lời hứa bị thu nhỏ thì mất lý do để bấm.',
      c:'Vẫn cần dấu hiệu nhận ra thương hiệu; chỉ là không cần cả khẩu hiệu.',
      d:'Đúng. Logo và màu cho sự nhất quán mà không chiếm chỗ của ý chính.'} },
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tp07-07', skill:'creative', read:'6 phút', t:'Câu 38 chữ này còn lại bao nhiêu nếu bỏ chữ thừa?',
  situation:'Một công ty dạy lái xe ô tô ở Hà Nội có đoạn quảng cáo: "Với mong muốn mang đến cho các bạn học viên một trải nghiệm học lái xe thật sự tốt nhất, chúng tôi xin trân trọng giới thiệu khoá học lái xe hạng B với lịch học vô cùng linh hoạt phù hợp." Câu dài 38 chữ, nhưng người đọc xong vẫn chưa biết lịch học thế nào.',
  concept:{ name:'Cắt chữ thừa',
    body:'Chữ thừa là chữ bỏ đi mà câu không mất nghĩa. Ba loại hay gặp: <b>đệm mở đầu</b> ("với mong muốn mang đến", "chúng tôi xin trân trọng"), <b>trạng từ phóng đại</b> ("thật sự", "vô cùng", "tuyệt đối"), và <b>tính từ trống</b> ("linh hoạt", "phù hợp" khi không nói linh hoạt thế nào). Cắt xong, chỗ trống thường lộ ra điều câu văn đang tránh nói — và đó là chỗ cần điền dữ kiện.' },
  example:'Cắt đệm và trạng từ: "Khoá học lái xe hạng B, lịch linh hoạt." Còn 9 chữ, nhưng "linh hoạt" vẫn trống. Điền dữ kiện: "Học lái xe hạng B buổi tối hoặc Chủ nhật, tự chọn giờ trên app." Câu cuối 16 chữ — ngắn hơn một nửa và lần đầu trả lời được câu người đi làm hỏi: tôi có học được ngoài giờ không.',
  takeaway:'Cắt đến khi câu mất nghĩa thì dừng; chỗ lộ ra sau khi cắt là chỗ cần dữ kiện.',
  apply:'Lấy một đoạn quảng cáo của bạn, gạch mọi chữ bỏ đi mà câu vẫn đúng. Đếm số chữ trước và sau.',
  mistakes:['Cắt cả con số và điều kiện vì nghĩ "ngắn là tốt".','Chỉ cắt mà không điền dữ kiện vào chỗ tính từ trống.'],
  q:[
  { type:'mcq', stem:'Đoạn 38 chữ về khoá học lái xe. Bạn đoán cắt chữ thừa còn lại khoảng bao nhiêu chữ có nghĩa?',
    options:[{k:'a',t:'Khoảng 30 chữ, vì hầu hết chữ đều cần cho câu văn trang trọng'},{k:'b',t:'Chưa tới 10 chữ'},
             {k:'c',t:'Không cắt được chữ nào, vì câu đã gọn và đủ ý rồi'},{k:'d',t:'Khoảng 20 chữ, bỏ phần lời chào nhưng giữ các từ nhấn mạnh'}],
    answer:'b', why:{a:'Phần lớn là đệm và trạng từ; bỏ đi câu vẫn đủ nghĩa.',
      b:'Đúng. Sau khi cắt còn "Khoá học lái xe hạng B, lịch linh hoạt" — 9 chữ.',
      c:'"Thật sự tốt nhất", "vô cùng" có thể bỏ mà câu không đổi nghĩa.',
      d:'Từ nhấn mạnh như "vô cùng" chính là chữ thừa.'} },
  { type:'mcq', stem:'Sau khi cắt còn "Khoá học lái xe hạng B, lịch linh hoạt". Bạn làm gì tiếp?',
    options:[{k:'a',t:'Đăng luôn vì câu đã ngắn gọn, rõ ràng'},{k:'b',t:'Thêm lại "vô cùng" trước "linh hoạt" để câu có sức nặng hơn'},
             {k:'c',t:'Thay "linh hoạt" bằng dữ kiện: buổi tối, Chủ nhật, tự chọn giờ'},{k:'d',t:'Đổi thành "lịch học siêu linh hoạt, phù hợp với tất cả mọi người"'}],
    answer:'c', why:{a:'Ngắn rồi nhưng "linh hoạt" vẫn là tính từ trống.',
      b:'Thêm trạng từ là quay về chữ thừa.',
      c:'Đúng. Chỗ trống lộ ra sau khi cắt là chỗ cần dữ kiện.',
      d:'Thêm "siêu" và "mọi người" vẫn không nói linh hoạt thế nào.'} },
  { type:'mcq', stem:'Trong câu "Sản phẩm thật sự vô cùng an toàn tuyệt đối cho làn da", chữ nào nên giữ?',
    options:[{k:'a',t:'"Thật sự" vì giúp tăng độ tin cậy của lời nói'},{k:'b',t:'"Tuyệt đối" vì đó là chữ mạnh nhất trong câu'},
             {k:'c',t:'Giữ cả ba trạng từ để nhấn mạnh lời cam kết'},{k:'d',t:'"An toàn cho làn da", rồi thêm bằng chứng'}],
    answer:'d', why:{a:'"Thật sự" không thêm bằng chứng; người đọc càng nghi.',
      b:'"Tuyệt đối" là lời hứa quá mức, dễ bị hỏi lại.',
      c:'Ba trạng từ chồng lên nhau làm câu kém tin hơn.',
      d:'Đúng. Giữ nghĩa, bỏ phóng đại, rồi điền bằng chứng như "đã thử trên da nhạy cảm".'} },
  { type:'calc', stem:'Đoạn quảng cáo gốc 38 chữ, bản cuối 16 chữ. Đã cắt bao nhiêu phần trăm số chữ? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:57.9, tol:0.2, wrong:[[42.1,'SAI_TINH_TOAN'],[137.5,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Số chữ cắt = 38 − 16 = 22.','Tỉ lệ cắt = 22 ÷ 38 ≈ <b>57,9%</b>.','42,1% là phần còn lại, không phải phần cắt.'] },
  { type:'mcq', stem:'Câu nào sau đây KHÔNG có chữ thừa?',
    options:[{k:'a',t:'Chúng tôi xin trân trọng thông báo chương trình ưu đãi đặc biệt'},{k:'b',t:'Mua 2 hộp tặng 1, đến hết 31/10'},
             {k:'c',t:'Với mong muốn phục vụ quý khách tốt hơn, cửa hàng mở cửa sớm'},{k:'d',t:'Sản phẩm thực sự rất tốt và vô cùng đáng tiền để mua'}],
    answer:'b', why:{a:'"Chúng tôi xin trân trọng thông báo" là đệm mở đầu.',
      b:'Đúng. Mỗi chữ đều mang thông tin; bỏ chữ nào cũng mất nghĩa.',
      c:'"Với mong muốn phục vụ quý khách tốt hơn" là đệm.',
      d:'"Thực sự", "rất", "vô cùng" đều thừa, và cả câu không có dữ kiện.'} },
  { type:'mcq', stem:'Một bạn cắt đoạn mô tả ưu đãi, bỏ luôn "áp dụng đơn từ 300k". Vấn đề là gì?',
    options:[{k:'a',t:'Không sao, điều kiện có thể nói khi khách nhắn tin hỏi'},{k:'b',t:'Câu vẫn còn quá dài, nên cắt thêm nữa cho gọn hơn'},
             {k:'c',t:'Chỉ cần thêm dấu sao để báo là có điều kiện riêng'},{k:'d',t:'Đã cắt mất dữ kiện; khách hiểu sai rồi thấy bị lừa'}],
    answer:'d', why:{a:'Khách hiểu sai từ đầu thì phản ứng xấu khi biết điều kiện.',
      b:'Vấn đề không phải độ dài mà là mất thông tin cần thiết.',
      c:'Dấu sao không nói điều kiện là gì.',
      d:'Đúng. Chữ thừa là chữ không mang nghĩa; điều kiện mang nghĩa quan trọng.'} },
  { type:'mcq', stem:'Làm sao biết một chữ là thừa?',
    options:[{k:'a',t:'Bỏ nó đi, nếu câu vẫn đúng nghĩa thì nó thừa'},{k:'b',t:'Chữ dài thì thay bằng chữ ngắn'},
             {k:'c',t:'Mọi tính từ trong quảng cáo đều là thừa'},{k:'d',t:'Chữ nào sếp không thích là thừa'}],
    answer:'a', why:{a:'Đúng. Phép thử đơn giản nhất: bỏ đi và đọc lại.',
      b:'Độ dài của chữ không quyết định nó có mang nghĩa.',
      c:'Tính từ có dữ kiện ("dày", "nhẹ 210 g") vẫn cần; chỉ tính từ trống là thừa.',
      d:'Sở thích cá nhân không phải tiêu chí về nghĩa.'} },
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tp07-08', skill:'channel', read:'7 phút', t:'Mô tả sản phẩm trên sàn: khách đọc gì trước khi thêm vào giỏ?',
  situation:'Một shop trên Shopee bán nồi chiên không dầu 5 lít, giá 1.290.000 đồng. Tiêu đề: "Nồi chiên không dầu cao cấp chính hãng giá tốt siêu sale". Mô tả mở bằng đoạn văn về "phong cách sống lành mạnh". Khung hỏi đáp có hàng chục câu giống nhau: "nướng được gà nguyên con không?", "lòng nồi có tháo rửa được không?".',
  concept:{ name:'Mô tả trả lời câu hỏi trước khi khách hỏi',
    body:'Trên sàn, khách so nhiều shop cùng lúc và lướt rất nhanh. <b>Tiêu đề</b> cần từ khoá người ta gõ tìm (loại, dung tích, đặc điểm chính), không cần tính từ. <b>Mô tả</b> nên mở bằng 3–5 gạch đầu dòng trả lời đúng những câu khách hay hỏi, mỗi dòng một dữ kiện. Nguồn tốt nhất cho các dòng này là khung hỏi đáp và đánh giá của chính shop, và của shop đối thủ: câu khách hỏi đi hỏi lại là thông tin mô tả đang thiếu.' },
  example:'Tiêu đề mới: "Nồi chiên không dầu 5L, lòng tháo rời, nướng gà 1,4 kg". Năm dòng đầu mô tả: vừa gà nguyên con đến 1,4 kg; lòng nồi chống dính tháo rửa được bằng máy; hẹn giờ 60 phút, 80–200°C; công suất 1.500W; bảo hành 12 tháng, đổi mới trong 7 ngày. Đoạn về lối sống lành mạnh chuyển xuống cuối. Sau khi sửa, câu hỏi lặp lại trong khung hỏi đáp giảm rõ, và thời gian khách ở lại trang dài hơn.',
  takeaway:'Câu khách hỏi đi hỏi lại chính là dòng mô tả bạn còn thiếu.',
  apply:'Mở trang sản phẩm của bạn hoặc đối thủ, chép 5 câu khách hỏi nhiều nhất. Viết mỗi câu thành một gạch đầu dòng dữ kiện.',
  mistakes:['Nhồi tiêu đề bằng "cao cấp, giá tốt, siêu sale".','Mở mô tả bằng đoạn văn cảm xúc, đẩy thông số xuống cuối.'],
  q:[
  { type:'mcq', stem:'Khung hỏi đáp có hàng chục câu "nướng được gà nguyên con không?". Bạn đoán điều đó nói gì về mô tả?',
    options:[{k:'a',t:'Khách lười đọc, thông tin đã có mà vẫn cứ hỏi'},{k:'b',t:'Sản phẩm có lỗi nên khách cần xác nhận lại trước khi mua'},
             {k:'c',t:'Đó là câu hỏi vui, không ảnh hưởng tới quyết định mua'},{k:'d',t:'Mô tả thiếu hoặc giấu thông tin khách cần nhất'}],
    answer:'d', why:{a:'Nếu thông tin nằm ở dòng đầu, rất ít người phải hỏi lại.',
      b:'Họ hỏi về khả năng dùng, không phải về lỗi.',
      c:'Một câu hỏi lặp lại hàng chục lần là điều kiện mua của nhiều người.',
      d:'Đúng. Câu hỏi lặp lại là thông tin mô tả đang thiếu.'} },
  { type:'mcq', stem:'Bạn viết lại tiêu đề sản phẩm trên sàn. Bạn chọn tiêu đề nào?',
    options:[{k:'a',t:'Nồi chiên không dầu cao cấp chính hãng giá tốt siêu sale'},{k:'b',t:'Nồi chiên không dầu 5L, lòng tháo rời, nướng gà 1,4 kg'},
             {k:'c',t:'Siêu phẩm nhà bếp hot nhất 2026 — mua ngay kẻo hết hàng'},{k:'d',t:'Sống khoẻ mỗi ngày cùng người bạn bếp núc thông minh'}],
    answer:'b', why:{a:'Toàn tính từ khách không tìm kiếm và không so được.',
      b:'Đúng. Có từ khoá tìm kiếm và dữ kiện khách dùng để so giữa các shop.',
      c:'Không có từ khoá loại sản phẩm, khó được tìm thấy.',
      d:'Câu cảm xúc, không có tên sản phẩm lẫn thông số.'} },
  { type:'mcq', stem:'Đoạn "phong cách sống lành mạnh" nên xử lý thế nào?',
    options:[{k:'a',t:'Xoá hẳn vì nội dung cảm xúc không có giá trị trên sàn'},{k:'b',t:'Để ở đầu vì nó tạo thiện cảm trước khi khách đọc thông số'},
             {k:'c',t:'Chuyển xuống dưới các dòng dữ kiện chính'},{k:'d',t:'Viết dài thêm để trang sản phẩm trông chuyên nghiệp hơn'}],
    answer:'c', why:{a:'Có thể giữ cho người muốn đọc thêm; chỉ cần đổi thứ tự.',
      b:'Khách trên sàn đang so; họ cần dữ kiện trước.',
      c:'Đúng. Dữ kiện trước, câu chuyện sau.',
      d:'Dài hơn không làm chuyên nghiệp hơn; nó đẩy dữ kiện ra xa.'} },
  { type:'mcq', stem:'Một shop bán áo sơ mi nhận nhiều đánh giá 3 sao kèm lời "mặc chật hơn tưởng". Nên thêm gì vào mô tả?',
    options:[{k:'a',t:'Bảng số đo ngực, vai, dài áo từng size, kèm chiều cao cân nặng mẫu'},{k:'b',t:'Dòng chữ in đậm "Form chuẩn, mặc là đẹp, cam kết hài lòng"'},
             {k:'c',t:'Khuyến khích khách đánh giá lại 5 sao để nhận thêm mã giảm giá'},{k:'d',t:'Ghi chú "Khách nên tăng size nếu thích mặc rộng rãi thoải mái"'}],
    answer:'a', why:{a:'Đúng. Số đo cụ thể giúp khách chọn đúng size trước khi mua.',
      b:'Lời hứa chung chung không sửa được việc chọn sai size.',
      c:'Không giải quyết nguyên nhân, và có thể vi phạm quy định của sàn.',
      d:'Có hướng đúng nhưng mơ hồ; tăng một hay hai size, số đo bao nhiêu?'} },
  { type:'calc', stem:'Trong 400 câu hỏi của khách tháng trước, 140 câu hỏi về việc tháo rửa lòng nồi và nướng gà. Tỉ lệ câu hỏi thuộc hai chủ đề này là bao nhiêu phần trăm?',
    unit:'%', ans:35, tol:0.1, wrong:[[285.7,'SAI_MAU_SO'],[65,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Tỉ lệ = số câu thuộc chủ đề ÷ tổng câu hỏi.','140 ÷ 400 = 0,35 = <b>35%</b>.','Hơn một phần ba câu hỏi chỉ cần hai dòng mô tả là trả lời xong.'] },
  { type:'mcq', stem:'Muốn biết khách thật sự cần thông tin gì cho một sản phẩm mới chưa có đánh giá, nguồn nào tốt nhất?',
    options:[{k:'a',t:'Hỏi đội sale xem họ nghĩ khách thích nghe điều gì nhất'},{k:'b',t:'Đọc hỏi đáp và đánh giá 1–3 sao của shop đối thủ cùng loại'},
             {k:'c',t:'Sao chép nguyên phần mô tả của nhà sản xuất bằng tiếng Anh'},{k:'d',t:'Dùng các từ khoá đang thịnh hành trên mạng xã hội tuần này'}],
    answer:'b', why:{a:'Đội sale đoán, còn đánh giá là lời khách thật.',
      b:'Đúng. Khách của đối thủ đã hỏi và phàn nàn đúng những điều khách của bạn sẽ hỏi.',
      c:'Mô tả nhà sản xuất viết theo tính năng, không theo câu hỏi của khách Việt.',
      d:'Từ khoá thịnh hành chưa chắc liên quan tới điều kiện mua.'} },
  { type:'mcq', stem:'Một bạn muốn thêm "hàng chuẩn xịn 100%, bao đẹp" vào đầu mô tả để tăng tin tưởng. Góp ý nào đúng?',
    options:[{k:'a',t:'Nên thêm, vì khách trên sàn rất sợ mua phải hàng giả, hàng nhái'},{k:'b',t:'Nên thêm, và in đậm cả câu cho khách thấy ngay từ đầu'},
             {k:'c',t:'Viết thành "hàng chuẩn xịn 200%" cho nổi bật hơn các shop khác'},{k:'d',t:'Thay bằng thứ kiểm được: tem bảo hành, hoá đơn, đổi trả 7 ngày'}],
    answer:'d', why:{a:'Nỗi sợ là thật, nhưng lời tự nhận không làm dịu nó.',
      b:'In đậm lời tự khen không biến nó thành bằng chứng.',
      c:'Phóng đại thêm làm khách nghi hơn.',
      d:'Đúng. Bằng chứng khách tự kiểm được mới giảm được nỗi lo hàng giả.'} },
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tp07-09', skill:'creative', read:'7 phút', t:'Trước khi bấm chạy: thay tên đối thủ vào, quảng cáo còn đúng không?',
  situation:'Một thương hiệu nước mắm ở Phú Quốc sắp chạy quảng cáo: "Nước mắm truyền thống thơm ngon đậm đà, chất lượng hàng đầu, được hàng triệu gia đình tin dùng." Ngân sách đợt này 30 triệu đồng. Trước khi duyệt, trưởng nhóm yêu cầu kiểm tra bản viết bằng ba phép thử.',
  concept:{ name:'Ba phép thử trước khi chạy',
    body:'<b>1. Thay tên đối thủ:</b> thay tên mình bằng tên một đối thủ; nếu câu vẫn đúng, câu chưa nói gì riêng. <b>2. Đọc to:</b> đọc thành tiếng như nói với một người bạn; chỗ nào vấp hoặc nghe như văn thông báo là chỗ cần viết lại. <b>3. Hỏi "chứng minh bằng gì?":</b> với mỗi lời khen, hỏi bằng chứng; không có thì bỏ hoặc thay bằng dữ kiện. Ba phép thử mất khoảng mười phút, rẻ hơn nhiều so với tiền chạy một bản viết rỗng.' },
  example:'Thay tên: "Nước mắm X truyền thống thơm ngon đậm đà, chất lượng hàng đầu" — đúng với mọi hãng, trượt. Đọc to: "chất lượng hàng đầu, được hàng triệu gia đình tin dùng" nghe như thông báo, không ai nói với bạn như vậy. Hỏi bằng chứng: "hàng triệu gia đình" không có số liệu. Bản mới: "Cá cơm và muối, ủ 12 tháng trong thùng gỗ. Độ đạm 40°N in trên nhãn." Thay tên đối thủ vào, câu không còn đúng — đó là dấu hiệu tốt.',
  takeaway:'Nếu thay tên đối thủ vào mà câu vẫn đúng, bạn đang trả tiền quảng cáo cho cả ngành.',
  apply:'Lấy quảng cáo sắp chạy, thay tên đối thủ lớn nhất vào và đọc to. Gạch mọi câu vẫn còn đúng.',
  mistakes:['Chỉ kiểm lỗi chính tả, bỏ qua kiểm tra nội dung.','Giữ lời khen không có bằng chứng vì "ai cũng viết vậy".'],
  q:[
  { type:'mcq', stem:'Thay tên một hãng nước mắm khác vào câu quảng cáo gốc. Bạn đoán câu có còn đúng không?',
    options:[{k:'a',t:'Không, vì mỗi hãng có công thức riêng nên câu chỉ đúng với mình'},{k:'b',t:'Vẫn đúng hoàn toàn — câu không nói gì riêng'},
             {k:'c',t:'Chỉ đúng nếu hãng kia cũng ở Phú Quốc và làm nước mắm truyền thống'},{k:'d',t:'Không thể biết nếu chưa chạy thử và đo lượt bấm thực tế'}],
    answer:'b', why:{a:'Công thức có thể khác, nhưng câu không nhắc tới công thức nào.',
      b:'Đúng. "Thơm ngon, chất lượng hàng đầu" hãng nào cũng tự nhận được.',
      c:'Câu không nhắc Phú Quốc; nó đúng với hầu hết mọi hãng.',
      d:'Phép thử này làm được ngay trên giấy, không cần chạy.'} },
  { type:'mcq', stem:'Câu "được hàng triệu gia đình tin dùng" không có số liệu kèm theo. Bạn làm gì?',
    options:[{k:'a',t:'Giữ nguyên, vì đây là câu quen thuộc khách đã chấp nhận'},{k:'b',t:'Đổi thành "hàng chục triệu gia đình" cho ấn tượng hơn'},
             {k:'c',t:'Chuyển sang cuối bài để giảm sự chú ý vào câu này'},{k:'d',t:'Bỏ, thay bằng dữ kiện kiểm được như độ đạm, thời gian ủ'}],
    answer:'d', why:{a:'Quen thuộc nghĩa là người đọc đã lướt qua nó từ lâu.',
      b:'Phóng đại thêm một lời không có bằng chứng.',
      c:'Đổi chỗ không làm câu có bằng chứng.',
      d:'Đúng. Lời không chứng minh được thì bỏ; dữ kiện trên nhãn thì khách tự kiểm.'} },
  { type:'mcq', stem:'Vì sao nên đọc to bản quảng cáo thay vì đọc thầm?',
    options:[{k:'a',t:'Để tai bắt được câu vấp, câu nghe như thông báo'},{k:'b',t:'Để kiểm tra chính xác độ dài quảng cáo tính theo từng giây'},
             {k:'c',t:'Để thu âm lại làm quảng cáo phát trên radio sau này'},{k:'d',t:'Để đồng nghiệp ngồi gần cùng nghe và góp ý trực tiếp'}],
    answer:'a', why:{a:'Đúng. Đọc thầm, mắt tự lướt qua chỗ lủng củng; đọc to thì vấp ngay.',
      b:'Độ dài có ích cho video, nhưng mục đích chính là nghe câu có tự nhiên không.',
      c:'Không liên quan tới mục đích kiểm tra câu chữ.',
      d:'Góp ý có ích, nhưng phép thử này tự làm một mình được.'} },
  { type:'calc', stem:'Ngân sách 30 triệu đồng. Nếu bản viết rỗng làm CTR chỉ bằng 1/3 bản tốt, với cùng số lượt hiển thị, số tiền "trả cho lượt hiển thị không tạo ra lượt bấm thêm" tương đương bao nhiêu triệu đồng so với bản tốt? (tính phần ngân sách mất đi = ngân sách × (1 − 1/3))',
    unit:'triệu đồng', ans:20, tol:0.1, wrong:[[10,'SAI_TINH_TOAN'],[90,'NGUOC_TAN_SUAT']], errors:['SAI_TINH_TOAN','NGUOC_TAN_SUAT'],
    steps:['Bản rỗng chỉ tạo 1/3 số lượt bấm của bản tốt với cùng tiền.','Phần hiệu quả mất đi = 30 × (1 − 1/3) = 30 × 2/3 = <b>20 triệu đồng</b>.','10 triệu là phần còn hiệu quả, không phải phần mất.'] },
  { type:'mcq', stem:'Một nhóm dùng phép thử thay tên đối thủ cho câu "Giao trong 2 giờ nội thành Cần Thơ, trễ hoàn phí ship". Kết quả nào có thể xảy ra?',
    options:[{k:'a',t:'Chắc chắn trượt, vì thay tên đối thủ nào vào thì câu cũng trượt'},{k:'b',t:'Chắc chắn đạt, vì có con số nên không bao giờ trùng với đối thủ'},
             {k:'c',t:'Đạt nếu đối thủ không cam kết được như vậy'},{k:'d',t:'Không áp dụng được vì phép thử chỉ dành cho câu có tính từ'}],
    answer:'c', why:{a:'Phép thử không phải lúc nào cũng trượt; câu có cam kết riêng sẽ đạt.',
      b:'Con số có thể trùng; nếu đối thủ cũng giao 2 giờ, câu chưa riêng.',
      c:'Đúng. Phép thử hỏi: đối thủ có nói được y như vậy và đúng không.',
      d:'Phép thử áp dụng cho mọi câu, kể cả câu có số.'} },
  { type:'mcq', stem:'Trưởng nhóm nói: "Kiểm tra mất thời gian, cứ chạy rồi xem số". Lập luận nào thuyết phục nhất để giữ bước kiểm tra?',
    options:[{k:'a',t:'Quy trình công ty bắt buộc phải kiểm tra trước khi chạy'},{k:'b',t:'Chạy trước sẽ bị nền tảng từ chối quảng cáo có câu sáo rỗng'},
             {k:'c',t:'Khách hàng sẽ báo cáo quảng cáo nếu thấy chữ sáo rỗng'},{k:'d',t:'Mười phút kiểm tra rẻ hơn nhiều so với tiền chạy bản rỗng'}],
    answer:'d', why:{a:'Viện quy trình không giải thích vì sao bước này đáng làm.',
      b:'Nền tảng không từ chối vì câu sáo; nó chỉ phân phối kém hơn.',
      c:'Rất ít người báo cáo; họ chỉ lướt qua.',
      d:'Đúng. So chi phí thời gian với chi phí ngân sách là lập luận người ra quyết định cần.'} },
  { type:'mcq', stem:'Câu nào qua được cả ba phép thử cho một hãng dầu gội thảo dược?',
    options:[{k:'a',t:'Dầu gội thảo dược thiên nhiên an toàn, lành tính cho mọi loại tóc'},{k:'b',t:'Chiết xuất bồ kết và vỏ bưởi, không silicon; chai 400 ml gội khoảng 2 tháng'},
             {k:'c',t:'Thương hiệu dầu gội thảo dược số 1 được yêu thích nhất hiện nay'},{k:'d',t:'Bí quyết mái tóc óng ả suôn mượt từ thiên nhiên dành cho bạn'}],
    answer:'b', why:{a:'Thay tên đối thủ vào vẫn đúng; "an toàn, lành tính" không có bằng chứng.',
      b:'Đúng. Thành phần, điều không có, và thời gian dùng đều kiểm được; đọc to nghe tự nhiên.',
      c:'"Số 1", "yêu thích nhất" không có bằng chứng.',
      d:'Câu sáo, hãng nào cũng dùng được.'} },
  ] },

] });
